private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("size must be positive");
    }
    // If the underlying array is null, simply allocate the requested size.
    if (data == null) {
        data = new byte[size];
        return;
    }
    int currentCapacity = data.length;
    // Compute a new capacity that can accommodate the additional bytes.
    long newCapLong = (long) currentCapacity * 2;
    long required = (long) currentCapacity + size;
    long newCap = Math.max(newCapLong, required);
    // Clamp to Integer.MAX_VALUE to avoid array size overflow.
    if (newCap > Integer.MAX_VALUE) {
        newCap = Integer.MAX_VALUE;
    }
    int newCapacity = (int) newCap;
