public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    // The smallest prime
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure we start with an odd number
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    // Upper bound for search to keep within 11% if desiredCapacity >= 1000
    int upperBound = desiredCapacity;
    if (desiredCapacity >= 1000) {
        // 11% of desiredCapacity
        int margin = (int) Math.floor(desiredCapacity * 0.11);
        // Avoid overflow
        if (Integer.MAX_VALUE - margin > desiredCapacity) {
            upperBound = desiredCapacity + margin;
        } else {
            upperBound = Integer.MAX_VALUE;
        }
    }
    while (candidate <= upperBound) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
    // If we exceed the bound, continue searching beyond it
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
}

