public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            throw new IllegalArgumentException("Trailing backslash at end of string");
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new IllegalArgumentException("Incomplete Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    sb.append((char) codePoint);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex, e);
                }
                i += 5; // skip over \uXXXX
                break;
            default:
                throw new IllegalArgumentException("Unknown escape sequence: \\" + next + " at position " + i);
        }
    }
    return sb.toString();
}<|return|>

