    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    try {
        // Create a circulator starting at the given node and direction.
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

        // If the start node is the same as the stop node, return immediately.
        if (start.equals(stop)) {
            return circ;
        }

        // Traverse the outer face until we find a node that satisfies the predicate
        // or until we reach the stop node.
        while (true) {
            Node current = circ.getNode();
            if (predicate.test(current)) {
                return circ;
            }
            if (current.equals(stop)) {
                return circ;
            }
            // Move to the next node in the specified direction.
            circ.advance(dir);
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context.
