public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int len = path.length();
    if (len == 0) {
        return null;
    }
    // Find the last file separator (handles both '/' and '\\')
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the last dot
    int lastDot = path.lastIndexOf('.');
    // If there is no dot, or the dot is part of the directory name, or the dot is the last character, return null
    if (lastDot <= lastSlash || lastDot == len - 1) {
        return null;
    }
    // Return the path without the extension
    return path.substring(0, lastDot);
