private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffixList = new ArrayList<>(n);
    long total = 0L;
    for (int i = 0; i < n; i++) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null element at index " + i);
        }
        total += val;
    }
    long suffixSum = 0L;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        temp[i] = (int) suffixSum; // cast to int; may overflow but matches return type
    }
    for (int i = 0; i < n; i++) {
        suffixList.add(temp[i]);
    }
    return new Pair<>(suffixList, total);
