public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Preserve whether the original path was absolute
    boolean isAbsolute = path.startsWith("/");

    // Normalize path: remove trailing slash unless it's the root "/"
    if (path.length() > 1 && path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Remove leading slash from relativePath if present (treat as relative)
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split components
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");

    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    // Process base path components
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pollLast();
            }
        } else {
            stack.offerLast(part);
        }
    }

    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pollLast();
            }
        } else {
            stack.offerLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }

    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If result is empty, return "." for relative paths or "/" for absolute root
    if (result.length() == 0) {
        return isAbsolute ? "/" : ".";
    }

    return result.toString();
